<script>document.addEventListener('DOMContentLoaded',()=>{const rows=document.querySelectorAll('.cart-row');const update=()=>{let total=0;rows.forEach(row=>{if(row.classList.contains('hidden'))return;const q=Number(row.querySelector('.quantity-value').textContent),price=Number(row.dataset.price);total+=q*price;row.querySelector('.item-price').textContent=`$${(q*price).toFixed(2)}`;});document.getElementById('cart-subtotal').textContent=`$${total.toFixed(2)}`;document.getElementById('cart-total').textContent=`$${total.toFixed(2)}`;if(total===0){document.getElementById('empty-cart').classList.remove('hidden');document.getElementById('cart-items').classList.add('hidden');}};document.querySelectorAll('.quantity-change').forEach(button=>button.addEventListener('click',()=>{const value=button.closest('.cart-row').querySelector('.quantity-value');value.textContent=Math.max(1,Number(value.textContent)+Number(button.dataset.step));update();}));document.querySelectorAll('.remove-item').forEach(button=>button.addEventListener('click',()=>{button.closest('.cart-row').classList.add('hidden');update();}));});</script>
